import unittest
import api

class IndependentBehavior(unittest.TestCase):
    def test_order(self): self.assertEqual(api.unique_values([9,3,9,1,3]),[9,3,1])
    def test_strings(self): self.assertEqual(api.unique_values(["z","a","z","m"]),["z","a","m"])
    def test_empty(self): self.assertEqual(api.unique_values([]),[])
    def test_input_unchanged(self):
        x=[8,1,8]; api.unique_values(x); self.assertEqual(x,[8,1,8])
    def test_helper(self): self.assertEqual(api.count_values([3,3]),2)
